		public void TestNoCasesFoundQueryResult()
		{
			var message = Factory.New<MQEDIMessage>();
			message.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.ADCVDCaseInformationQueryResponse;
			message.EM_MessageNum = "58230";
			message.EM_ReceiveTransmit = MQEDIMessage.Direction.Receive;
			message.EM_MessageText = "B001101SV9AC                                               58230                RXQ2C 000001 REF ID:                014 QUERY COMPLETE - NO AD/CVD CASES FOUND  Y  1101SV9AC00000";

			var message2 = Factory.New<MQEDIMessage>();
			message2.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			message2.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.ADCVDCaseInformationQueryResponse;
			message2.EM_MessageNum = "58243";
			message2.EM_ReceiveTransmit = MQEDIMessage.Direction.Receive;
			message2.EM_MessageText = "B001101SV9AC                                               58243                RXQ1E 000001 REF ID: 351812000      003 CASE NUMBER NOT FOUND FOR QUERY         RXQ1E 000001 REF ID: 351811000      003 CASE NUMBER NOT FOUND FOR QUERY         RXQ1E 000001 REF ID: 557222011      003 CASE NUMBER NOT FOUND FOR QUERY         RXQ1E 000001 REF ID: 557806003      003 CASE NUMBER NOT FOUND FOR QUERY         RXQ1E 000001 REF ID: 427009999      003 CASE NUMBER NOT FOUND FOR QUERY         RXQ1E 000002 REF ID: 427046000      003 CASE NUMBER NOT FOUND FOR QUERY         RXQ1E 000002 REF ID: 427203012      003 CASE NUMBER NOT FOUND FOR QUERY         Y  1101SV9AC00000";

			Factory.Save();

			Env.OutgoingCustomsMailManager.EmailsCreated.Clear();
			new USRIncomingMessageProcessor().ExecuteBatch();

			var email = Env.OutgoingCustomsMailManager.EmailsCreated[0];
			AssertEquals("Email Subject should not contains '(Failure)', because query completed",
				"AntiDumping/Countervailing Query Response", email.Subject);
			Assert("Email Body", email.Body.Contains("QUERY COMPLETE - NO AD/CVD CASES FOUND"));

			email = Env.OutgoingCustomsMailManager.EmailsCreated[1];
			AssertEquals("Email Subject should not contains '(Failure)', because query completed, but without results",
				"AntiDumping/Countervailing Query Response", email.Subject);
			Assert("Email Body", email.Body.Contains("<td>351812000</td><td>003</td><td>CASE NUMBER NOT FOUND FOR QUERY"));
		}

