		public void TestQueryDetailsInOutgoingEmail()
		{
			var outgoingMessage = Factory.New<MQEDIMessage>();
			outgoingMessage.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			outgoingMessage.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.ADCVDCaseInformationQuery;
			outgoingMessage.EM_ReceiveTransmit = MQEDIMessage.Direction.Transmit;
			outgoingMessage.EM_MessageText = "B  3901SV9AD                                               HYEDUSCMT_1001XX     Q2 A GB 9001201024 1233321 MID1111         FS112333        060517               Y  3901SV9AD";

			var incomingMessage = Factory.New<MQEDIMessage>();
			incomingMessage.EM_ApplicationCode = EDIMessage.ApplicationCodes.USCustomsImport;
			incomingMessage.EM_MessageType = ACEApplicationIdentifierCodeList.Codes.ADCVDCaseInformationQueryResponse;
			incomingMessage.EM_MessageNum = "HYEDUSCMT_1001XX";
			incomingMessage.EM_ReceiveTransmit = MQEDIMessage.Direction.Receive;
			incomingMessage.EM_MessageText = "B004909SV9AC                                               HYEDUSCMT_1001XX     RXQ2C 000001 REF ID:                014 QUERY COMPLETE - NO AD/CVD CASES FOUND  Y  4909SV9AC00000";
			Factory.Save();

			outgoingMessage.EM_MessageNum = "HYEDUSCMT_1001XX";
			Factory.Save();

			Env.OutgoingCustomsMailManager.EmailsCreated.Clear();
			new USRIncomingMessageProcessor().ExecuteBatch();

			var email = Env.OutgoingCustomsMailManager.EmailsCreated[0];
			Assert("Case Status/Country/HTS/Manufacturer ID/Foreign Shipper MID/Date Since Last Update/TSUSA should be included in email body",
				email.Body.Contains("<tr><td>Case Status</td><td>A</td></tr><tr><td>Country</td><td>GB</td></tr><tr><td>HTS</td><td>9001201024</td></tr><tr><td>Manufacturer MID</td><td>MID1111</td></tr><tr><td>Foreign Shipper MID</td><td>FS112333</td></tr><tr><td>Date Since Last Update</td><td>05-Jun-17</td></tr><tr><td>TSUSA</td><td>1233321</td></tr>"));
		}

